361	\begin{lemma}[Approximate commutation from joint consistency]\label{lem:commutation-analysis}
362		\lean{MIPStarRE.QPBT.opDistSq_commutator_le}
363		\leanok
364		\uses{def:povm-distance, def:povm-conventions}
365		Let $\{A^x_{a,\,b}\}$, $\{B^x_{a,\,b,\,c}\}$, $\{C^x_{a,\,c}\}$ be POVMs. Suppose $\{B^x_{a,\,b,\,c}\}$ is projective, and
366		\begin{align*}
367			A^x_{a,\,b} \ot \Id_B &\approx_\delta \Id_A \ot B^x_{a,\,b}\,,\\
368			C^x_{a,\,c} \ot \Id_B &\approx_\delta \Id_A \ot B^x_{a,\,c}\,,
369		\end{align*}
370		where $B^x_{a,\,b} = \sum_c B^x_{a,\,b,\,c}$ and $B^x_{a,\,c} = \sum_b B^x_{a,\,b,\,c}$ are the marginals of Definition~\ref{def:povm-conventions}. Then the following approximate commutation relation holds:
371		\[
372			[A^x_{a,\,b},\, C^x_{a,\,c}] \ot \Id_B \approx_\delta 0\,.
373		\]
