379		\begin{equation}\label{eq:commutation-analysis-1}
380			A^x_{a,\,b}\, C^x_{a,\,c} \ot \Id_B \approx_\delta A^x_{a,\,b} \ot B^x_{a,\,c}\,.
381		\end{equation}
382		Similarly, applying Lemma~\ref{fact:add-a-proj} to $A^x_{a,\,b} \ot \Id_B \approx_\delta \Id_A \ot B^x_{a,\,b}$ with the multiplier family $\{\Id_A \ot B^x_{a,\,c}\}$, and using that $\{B^x_{a,\,b,\,c}\}$ is projective,
383		\begin{equation}\label{eq:commutation-analysis-2}
384			A^x_{a,\,b} \ot B^x_{a,\,c} \approx_\delta \Id_A \ot B^x_{a,\,c}\, B^x_{a,\,b} = \Id_A \ot B^x_{a,\,b,\,c}\,.
385		\end{equation}

